const Autocomplete = ({ options, value, onChange }) => {
  const [activeOption, setActiveOption] = useState(null);
  const [searchValue, setSearchValue] = useState(value);

  useEffect(() => {
    setSearchValue(value);
  }, [value]);

  const handleSearch = (event) => {
    const searchValue = event.target.value;
    setSearchValue(searchValue);
  };

  const handleSelect = (option) => {
    setSearchValue(option.value);
    onChange(option);
  };

  const handleKeyDown = (event) => {
    if (event.key === "ArrowDown" && activeOption !== null) {
      setActiveOption(activeOption.next);
    } else if (event.key === "ArrowUp" && activeOption !== null) {
      setActiveOption(activeOption.prev);
    } else if (event.key === "Enter" && activeOption !== null) {
      handleSelect(activeOption.value);
    }
  };

  const getOptions = () => {
    const filteredOptions = options.filter((option) => {
      const optionValue = option.value.toLowerCase();
      const searchValue = searchValue.toLowerCase();
      return optionValue.includes(searchValue);
    });
    return filteredOptions.map((option, index) => (
      <option key={index} value={option.value} data-index={index}>
        {option.label}
      </option>
    ));
  };

  return (
    <div>
      <input
        type="text"
        value={searchValue}
        onChange={handleSearch}
        onKeyDown={(event) => handleKeyDown(event)}
        placeholder="Search..."
      />
      {getOptions()}
      {activeOption && (
        <div
          className="autocomplete-suggestion"
          onClick={() => handleSelect(activeOption.value)}
